"""Five prism currents: exact integer and binary certificates. Python standard library."""
import base64,json,zlib
from itertools import product,permutations,combinations_with_replacement,combinations
from collections import Counter
def can(h):return min(h,tuple(-x%5 for x in h))
T=sorted({can((a,b,(-a-b)%5)) for a,b in product(range(5),repeat=2) if a or b})
def gauge(x):
 return min(tuple(sorted(can(tuple(s*h[w]%5 for w in pi)) for h in x)) for s in (1,2) for pi in permutations(range(3)))
def alphabet(h):return tuple(y for x in h for y in (x,(-x)%5))
def rowset(w):
 return tuple(36*s+6*w[i]+w[j] for s,(i,j) in enumerate(combinations(range(len(w)),2)))
def data(k):
 words=[w for w in product(range(6),repeat=k) if max(w.count(2*j)+w.count(2*j+1) for j in range(3))<=2]
 rows=[rowset(w) for w in words]
 rhs=tuple(2-int(a//2==b//2) for _ in combinations(range(k),2) for a in range(6) for b in range(6))
 return words,rows,rhs
def parity_reject(cols,rhs):
 base={};r=sum((v%2)<<i for i,v in enumerate(rhs))
 for col in cols:
  y=sum(1<<j for j in col)
  while y:
   k=y.bit_length()-1
   if k not in base:base[k]=y;break
   y^=base[k]
 while r and r.bit_length()-1 in base:r^=base[r.bit_length()-1]
 return bool(r)
