orbits=sorted({gauge(z) for z in combinations_with_replacement(T,5)})
assert len(orbits)==408 and len(cert)==66
w5,c5,b5=data(5);w6,c6,b6=data(6)
stats=Counter()
for idx,hs in enumerate(orbits):
 if sum(z*z for h in hs for z in h)%5:stats['norm']+=1;continue
 hh=list(map(alphabet,hs))
 def ok(w):return sum(h[w[i]] for i,h in enumerate(hh))%5==0
 cover=set().union(*(set(c) for w,c in zip(w5,c5) if ok(w)))
 if len(cover)<len(b5):stats['uncovered']+=1;continue
 u=cert[str(idx)];assert len(u)==len(b6)
 allowed=[c for w,c in zip(w6,c6) if ok(w)];values=[sum(u[i] for i in c) for c in allowed];v=sum(x*y for x,y in zip(u,b6))
 assert min(values)>=0
 if v<0:stats['strict']+=1
 else:
  assert idx==93 and v==0 and len(allowed)==1224
  rem=[c for z,c in zip(values,allowed) if z==0]
  assert len(rem)==620 and parity_reject(rem,b6);stats['face_plus_parity']+=1
assert stats==dict(norm=326,uncovered=16,strict=65,face_plus_parity=1)
print('408 five-block orbits:',stats,'; exposed face 1224 -> 620, binary inconsistent')
